// Verify the signed envelope before any work. Crypto only; no business logic (same scheme as W02).
const crypto = require('crypto');
const b = $json.body || {};
const ts = String(b.ts ?? '');
const payload = typeof b.payload === 'string' ? b.payload : '';
const sig = String(b.sig ?? '');
const expected = 'sha256=' + crypto.createHmac('sha256', $vars.MD_HMAC_SECRET).update(`${ts}.${payload}`).digest('hex');
const fresh = /^\d+$/.test(ts) && Math.abs(Date.now() / 1000 - Number(ts)) <= 300;
const a = Buffer.from(expected);
const g = Buffer.from(sig);
const sigOk = a.length === g.length && crypto.timingSafeEqual(a, g);
let parsed = null;
if (sigOk && fresh) {
  try { parsed = JSON.parse(payload); } catch (e) { parsed = null; }
}
const valid = parsed !== null && typeof parsed === 'object';
return [{ json: { valid, reason: valid ? 'ok' : !sigOk ? 'bad_signature' : !fresh ? 'stale' : 'bad_payload', payload: valid ? parsed : null } }];

// Whitelist the sheet columns. Pseudonymous participant code only: no name, phone, email or free
// text ever reaches the sheet (FIELD_STUDY §10). Shape checks only; the score is the server's.
const p = $('Verify envelope (HMAC)').first().json.payload || {};
if (p.event !== 'session_end' || p.cohort !== 'field_test') return [];
const eventId = String(p.event_id ?? '');
if (!/^[A-Za-z0-9_.:-]{8,64}$/.test(eventId)) throw new Error('bad event_id');
const code = String(p.participant_code ?? '');
if (!/^P-\d{3,4}$/.test(code)) throw new Error('bad participant_code');
const game = String(p.game ?? '');
if (!/^[a-z][a-z0-9_]{1,31}$/.test(game)) throw new Error('bad game');
const sid = typeof p.session_id === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(p.session_id) ? p.session_id : '';
const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : '');
const cal = p.calibration && typeof p.calibration === 'object' ? p.calibration : {};
const iso = (v) => (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}T[0-9:.]+(Z|[+-]\d{2}:\d{2})$/.test(v) ? v : '');
return [{ json: {
  event_id: eventId,
  participant_code: code,
  game,
  session_id: sid,
  score: num(p.score),
  latency_ms: num(p.latency_ms),
  calibration_n: num(cal.n),
  calibration_brier: num(cal.brier),
  calibration_overconfidence: num(cal.overconfidence),
  server_checked: p.server_checked === true,
  verified_at: iso(p.verified_at),
  received_at: new Date().toISOString(),
} }];

// Build + sign API-67 POST /internal/jobs/nightly_stats. One key per IST hour, so a retried or
// duplicated trigger starts one run. Reshape only (D-16).
const crypto = require('crypto');
const hour = $now.setZone('Asia/Kolkata').toFormat("yyyy-MM-dd'T'HH");
const statsId = `stats-${hour}`;
const body = JSON.stringify({ args: { stats_id: statsId } });
const ts = Math.floor(Date.now() / 1000).toString();
const v1 = crypto.createHmac('sha256', $vars.MD_HMAC_SECRET).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, signature: `t=${ts},v1=${v1}`, idempotency_key: `nightly-stats:${hour}`, stats_id: statsId } }];

// Presentation only: every number comes from API-71, computed by the backend and the pre-registered
// nazar_stats.mjs (RW-4). n8n computes no statistic.
const s = $json || {};
const z = s.nazar || {};
const j = s.journey_test || {};
const c = s.counters || {};
const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? String(v) : 'n/a');
const pct = (v) => (typeof v === 'number' && Number.isFinite(v) ? `${Math.round(v * 100)}%` : 'n/a');
const ci = Array.isArray(z.r_ci95) ? ` (95% CI ${z.r_ci95.map(num).join(' to ')})` : '';
let runId = 'n/a';
try { runId = $('API-67 start nightly_stats').first().json.body?.run_id ?? 'n/a'; } catch (e) { runId = 'n/a'; }
const lines = [
  `*Field test · hourly summary* (stats as of ${s.as_of ?? 'unknown'})`,
  `• Nazar participants: ${num(z.participants)} · below 60/100: ${pct(z.below_kerala_60_pct)} · r(LL quiz, Nazar) = ${num(z.r_ll_quiz_vs_nazar)}${ci}`,
  `• Journey-test participants: ${num(j.participants)}`,
  `• Game sessions counted: ${num(c.game_sessions_counted)} · plans computed: ${num(c.plans_computed)}`,
  `_Convenience sample (${z.sample ?? 'n/a'}); analysis pre-registered. This hour's nightly_stats run (${runId}) shows in the next summary._`,
];
return [{ json: { slack_text: lines.join('\n') } }];
